;==============================================================================
; _upVImp / _upVfsBank -- the callee module's bank, and the
; entry points inside it.  GENERATED by tools/gen_mod_imports.py; edit the
; table there, not this file.
;
; POPULATED ONCE, AT mod_init, from the vtable the loader resolves.  Zero
; until then, which is why the module refuses to run any C when a resolve
; fails -- a shim reading a zero would pile-call bank 0 offset $FFFF and the
; machine would come apart a long way from the cause.
;==============================================================================
_upVfsBank      DS      2               ; the callee's bank, in the low byte
_upVImp         DS      VFSCORE_COUNT*2

;------------------------------------------------------------------------------
; bread(vp, blkno, bpp) -> errno.  12 argument bytes.
;------------------------------------------------------------------------------
bread           MX      %00
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     |_upVImp+VFSCORE_Bread
                                        ; MODBANK-OK: entered from C, which left
                                        ;   DBR on our bank -- and read HERE,
                                        ;   before the switch below, for exactly
                                        ;   that reason
                TAX                             ; X = target offset in the callee
                SEP     #$20
                MX      %10
                LDA     |_upVfsBank    ; MODBANK-OK: same, still before the
                                        ;   switch
                PHA                             ; one byte on...
                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; upvret_bread is in OUR bank
                PEA     upvret_bread-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
upvret_bread    TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #12
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL

